/** Practical expansion from Rory's July 2026 Training Audit and 36 Week Plan.
 * These are learning activities, not replacements for persisted lesson IDs, gates or awards.
 * A course week is a sequence marker: weather and crop stage decide when field work is possible.
 * Technical figures remain in the existing readings; these activities invent no crop prescriptions.
 */
export interface FieldCycle {
  id: string;
  week?: number;
  title: string;
  lessonIds: string[];
  why: string;
  see: string;
  steps: string[];
  record: string;
  reflect: string;
  mentorCheck: string;
  whenBlocked: string;
  sourceIds?: string[];
}

