export const ALL_FIELD_CYCLES = [...CORE_FIELD_CYCLES, ...ELECTIVE_FIELD_PATHWAYS.flatMap((p) => p.cycles)];
export function fieldworkForLesson(lessonId: string): FieldCycle[] {
  return ALL_FIELD_CYCLES.filter((cycle) => cycle.lessonIds.includes(lessonId));
}
